<?php use App\Core\Csrf; $students=$students??[]; $channels=$channels??[]; $today=$today??date('Y-m-d'); $mpesa=array_values(array_filter($channels,static fn($c)=>strtolower((string)$c['type'])==='mpesa')); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payments | EduSasa</title><style>body{font-family:system-ui,sans-serif;background:#f6f7fb;color:#172033}.wrap{max-width:760px;margin:30px auto;padding:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:22px;margin-bottom:18px}label{display:block;margin:12px 0}input,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #ccd1db;border-radius:8px;margin-top:5px}button,a{padding:10px 14px;border:0;border-radius:8px;background:#172033;color:#fff;text-decoration:none;display:inline-block;margin-top:12px}.muted{color:#667085}.notice{background:#f3f4f6;border-radius:8px;padding:12px;margin-top:10px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><p><a href="/finance">← Finance</a></p><h1>Payments</h1><section class="card"><h2>M-Pesa STK Push</h2><p class="muted">Send a payment prompt to the student's phone. The payment is only posted after Safaricom confirms it.</p><?php if(!$mpesa): ?><div class="notice">No active M-Pesa payment channel is configured. Add one under <a href="/finance/payment-methods">Payment Methods</a>.</div><?php else: ?><form method="post" action="/finance/payments/mpesa/stk"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token(),ENT_QUOTES) ?>"><label>Student<select name="student_id" required><option value="">Select student</option><?php foreach($students as $student): ?><option value="<?= (int)$student['id'] ?>"><?= htmlspecialchars($student['admission_no'].' — '.$student['first_name'].' '.$student['last_name']) ?></option><?php endforeach; ?></select></label><label>Payment channel<select name="channel_id" required><?php foreach($mpesa as $channel): ?><option value="<?= (int)$channel['id'] ?>"><?= htmlspecialchars($channel['name']) ?></option><?php endforeach; ?></select></label><div class="grid"><label>Amount (KES)<input type="number" name="amount" min="1" step="1" required></label><label>Student phone<input name="phone" placeholder="07XXXXXXXX" required></label></div><label>Invoice ID <input type="number" name="invoice_id" min="1" placeholder="Optional — allocates payment to this invoice"></label><button type="submit">Send STK Push</button></form><?php endif; ?></section><section class="card"><h2>Record Manual Payment</h2><form method="post" action="/finance/payments"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token(),ENT_QUOTES) ?>"><label>Student<select name="student_id" required><option value="">Select student</option><?php foreach($students as $student): ?><option value="<?= (int)$student['id'] ?>"><?= htmlspecialchars($student['admission_no'].' — '.$student['first_name'].' '.$student['last_name']) ?></option><?php endforeach; ?></select></label><div class="grid"><label>Receipt No.<input name="receipt_no" required placeholder="RCPT-2026-0001"></label><label>Date<input type="date" name="payment_date" value="<?= htmlspecialchars($today) ?>" required></label></div><label>Amount (KES)<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Method<select name="method" required><?php foreach($channels as $channel): ?><?php if((int)$channel['allow_staff_entry']===1): ?><option value="<?= htmlspecialchars($channel['name'],ENT_QUOTES) ?>"><?= htmlspecialchars($channel['name']) ?></option><?php endif; ?><?php endforeach; ?></select></label><label>Reference<input name="reference" placeholder="Transaction/reference number"></label><label>Payer name<input name="payer_name"></label><button type="submit">Record Payment</button></form></section></main></body></html>
